import { describe, expect, it } from "vitest";
import fs from "node:fs/promises";
import os from "node:os";
import path from "path";
import { telegramPlugin, setTelegramRuntime } from "../../extensions/telegram/index.js";
import * as replyModule from "../auto-reply/reply.js";
import type { OpenClawConfig } from "../config/config.js";
import { setActivePluginRegistry } from "../plugins/runtime.js";
import { createPluginRuntime } from "../plugins/runtime/index.js";
import { createTestRegistry } from "../test-utils/channel-plugins.js";
import { runHeartbeatOnce } from "./heartbeat-runner.js";

function installTestRuntime() {
  const runtime = createPluginRuntime();
  setTelegramRuntime(runtime);
  setActivePluginRegistry(
    createTestRegistry([{ pluginId: "telegram", plugin: telegramPlugin as any, source: "test" }]),
  );
}

async function withTempSandbox<T>(
  fn: (ctx: { tmpDir: string; storePath: string; replySpy: any }) => Promise<T>,
): Promise<T> {
  installTestRuntime();
  const tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "hb-forced-test-"));
  await fs.writeFile(path.join(tmpDir, "HEARTBEAT.md"), "- Check status\n", "utf-8");
  const storePath = path.join(tmpDir, "sessions.json");
  const replySpy = require("vitest").vi.spyOn(replyModule, "getReplyFromConfig");
  try {
    return await fn({ tmpDir, storePath, replySpy });
  } finally {
    replySpy.mockRestore();
    await fs.rm(tmpDir, { recursive: true, force: true });
  }
}

describe("resolveHeartbeatSession forced session routing", () => {
  it("routes heartbeat to forced session even when agentId differs from resolvedAgentId", async () => {
    await withTempSandbox(async ({ tmpDir, storePath, replySpy }) => {
      // Seed a codingxia session in the store
      const codingxiaSessionKey = "agent:codingxia:feishu:direct:ou_test123";
      const mainSessionKey = "agent:main:feishu:default:direct:ou_main456";

      // Write session store with both sessions
      await fs.writeFile(
        storePath,
        JSON.stringify({
          [codingxiaSessionKey]: {
            sessionId: "sid-codingxia",
            updatedAt: Date.now(),
            lastChannel: "feishu",
            lastProvider: "feishu",
            lastTo: "ou_test123",
          },
          [mainSessionKey]: {
            sessionId: "sid-main",
            updatedAt: Date.now(),
            lastChannel: "feishu",
            lastProvider: "feishu",
            lastTo: "ou_main456",
          },
        }),
      );

      const cfg: OpenClawConfig = {
        agents: {
          defaults: {
            workspace: tmpDir,
            heartbeat: {
              every: "5m",
              // No explicit target — routing should be determined by forcedSessionKey
            },
          },
        },
        session: { store: storePath, scope: "per-sender" },
      };

      // Mock reply — record which sessionKey it receives
      let capturedCtx: any = null;
      replySpy.mockImplementation(async (ctx: any) => {
        capturedCtx = ctx;
        return { text: "ok" };
      });

      // Call runHeartbeatOnce with forcedSessionKey for codingxia
      await runHeartbeatOnce({
        cfg,
        agentId: "main", // resolvedAgentId = "main"
        opts: {
          sessionKey: codingxiaSessionKey, // forced to codingxia
          reason: "test",
        },
        deps: {
          getQueueSize: () => 0,
          nowMs: () => Date.now(),
        },
      });

      // The heartbeat should have been delivered to the codingxia session,
      // not to agent:main:main
      expect(capturedCtx).not.toBeNull();
      // Verify the delivery target used the forced session's lastTo
      expect(capturedCtx.To).toBe("ou_test123");
      expect(capturedCtx.sessionKey).toBe(codingxiaSessionKey);
    });
  });
});

